// Existing authenticated private-bus HTTP scope; no SDK/modem/service mutations.
#[tokio::test]async fn relation_intent_http_is_authenticated_bounded_read_only_and_cannot_accept_permission_fields(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/relation-intents";
    let(status,_,body)=account_request(&served,reqwest::Method::GET,path,None,None).await;assert_eq!(status,StatusCode::UNAUTHORIZED);no_secrets(&body);let cookie=authenticate(&served).await;
    for query in ["?limit=0","?limit=129","?limit=128&token=fixture-private","?limit=128&uid=fixture-private","?limit=128&claim_nonce=fixture-private"]{let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("{path}{query}"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}
    assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());assert!(state.app.app_logins.list().unwrap().is_empty());
}
#[tokio::test]async fn relation_intent_http_reports_preparing_without_uid_or_native_write_and_empty_write_history_is_not_clearance(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");
    let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":relation_http_config(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);
    state.app.database.with_conn(|c|c.execute("INSERT INTO app_voice_relation_intents(line_id,revision,user_nonce,body_hash,run_nonce,claim_nonce,configuration_hash,target_kind,additions,updates,removals,state,updated_at) VALUES(?1,1,?2,zeroblob(32),?3,?4,zeroblob(32),'buddy',1,0,0,0,'2026-01-01T00:00:00Z')",rusqlite::params![line,"a".repeat(32),"b".repeat(32),"c".repeat(32)]).map_err(|_|"fixture data only")).unwrap();
    let base=format!("/api/non-3gpp/accounts/{line}");let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("{base}/relation-intents?limit=128"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);no_secrets(&body);let data:serde_json::Value=serde_json::from_str(&body).unwrap();let row=&data["data"][0];assert_eq!(row["state"],"preparing");assert!(row["write_id"].is_null());assert_eq!(row["additions"],1);assert_eq!(row["nonce_tag"].as_str().unwrap().len(),64);
    for private in ["body_hash","run_nonce","claim_nonce","configuration_hash","user_nonce","uid","token","ready","grant",&"a".repeat(32)]{assert!(!body.contains(private));}
    let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("{base}/relation-writes?limit=128"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);assert_eq!(serde_json::from_str::<serde_json::Value>(&body).unwrap()["data"],serde_json::json!([]));assert_eq!(state.app.app_accounts.get(&line,100).await.unwrap().phase,"stopped");
    let count:i64=state.app.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_runtime_leases",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(count,0);
}
#[tokio::test]async fn relation_intent_http_corrupt_preparation_snapshot_is_rejected_not_echoed_or_retired(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");
    let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":relation_http_config(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);
    state.app.database.with_conn(|c|c.execute("INSERT INTO app_voice_relation_intents(line_id,revision,user_nonce,body_hash,run_nonce,claim_nonce,configuration_hash,target_kind,additions,updates,removals,state,updated_at) VALUES(?1,1,?2,zeroblob(32),?3,?4,zeroblob(32),'group',1,0,0,0,'private-fixture-data')",rusqlite::params![line,"a".repeat(32),"b".repeat(32),"c".repeat(32)]).map_err(|_|"fixture data only")).unwrap();
    let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/relation-intents?limit=128"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::INTERNAL_SERVER_ERROR);no_store(&headers);no_secrets(&body);assert!(!body.contains("private-fixture-data"));
    let state_value:i64=state.app.database.with_conn(|c|c.query_row("SELECT state FROM app_voice_relation_intents WHERE line_id=?1",[&line],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(state_value,0,"a read/error cannot clear unknown preparation or grant a new native action");
}
